.ds-btn { display: inline-flex; align-items: center; justify-content: center; font-weight: 500; font-family: 'Plus Jakarta Sans', sans-serif; text-transform: uppercase; border-radius: 0px; border: 2px solid var(--color-text-primary, #0a0a0a); transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1); cursor: pointer; }
.ds-btn-primary { background: var(--color-text-primary, #0a0a0a); color: var(--color-bg, #fafafa); padding: 16px 32px; font-size: 1rem; }
.ds-btn-primary:hover { opacity: 0.9; }

